import re

# Check all txt files in resources for any ESF data
import os
for f in os.listdir('/app/resources'):
    if f.endswith('.txt') and not f.startswith('.'):
        with open(f'/app/resources/{f}', 'r') as file:
            content = file.read()
            if 'Total assets' in content and 'ESF' in content:
                print(f"File: {f}")
                # Find lines with Total assets and Dec 31 dates
                lines = content.split('\n')
                for i, line in enumerate(lines):
                    if 'Total assets' in line or ('Dec. 31' in line or 'December' in line):
                        print(f"  {i}: {line[:200]}")
EOF
